-- ── 1502 Cigars (nicaragua) ──

INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('1502 Cigars',
        'nicaragua',
        '2011-2012 — Global Premium Cigars',
        'Sans usine — Plasencia Cigars S.A., Estelí',
        'cigarjournal.com « 1502 Cigars: Enrique Sanchez is Proudly Nicaraguan » (Enrique Sánchez Icaza, Global Premium Cigars, fondée en 2012 ; roulée chez Plasencia à Estelí ; le nom est l''année où Colomb atteint la côte du Nicaragua) ; globalpremiumcigars.com et cuencacigars.com (fondée en 2011 — l''écart d''un an est dit dans la fiche ; lignes Emerald, Ruby, Black Gold, XO, Nicaragua) ; halfwheel.com',
        '1502 est l''année où Christophe Colomb touche la côte du Nicaragua, et Enrique Sánchez Icaza l''a prise pour nom parce qu''il est nicaraguayen et tient à le dire. Sa société, Global Premium Cigars, date de 2011 selon son propre site et de 2012 selon la presse du métier — un an d''écart que cette fiche laisse ouvert.

Elle n''a pas d''usine, et ne le cache pas : ses cigares sont roulés chez Plasencia, à Estelí, la fabrique dont l''atlas porte la fiche et qui roule aussi Crux et Blanco. Une maison de cette liste sur trois passe par Plasencia ; c''est la mesure du rôle de cette famille dans la scène boutique.

Le catalogue est rangé par pierres et par métaux — Emerald, Ruby, Black Gold — avec un XO au-dessus et un Nicaragua tout simple. Le classement au Nicaragua ne fait pas débat : le fondateur, la feuille et l''atelier y sont.',
        '[{"name":"1502 Emerald","color":"#2E6B4A","force":"Medium","wrapper":"Non divulguée","vitolas":[],"story":"L''émeraude — la ligne d''entrée, par la couleur."},{"name":"1502 Ruby","color":"#8B1A1A","force":"Medium-Full","wrapper":"Non divulguée","vitolas":[],"story":"Le rubis."},{"name":"1502 Black Gold","color":"#2E2E2E","force":"Full","wrapper":"Non divulguée","vitolas":[],"story":"L''or noir — le plus corsé des trois."}]',
        '1502 is the year Christopher Columbus touched the coast of Nicaragua, and Enrique Sánchez Icaza took it as a name because he is Nicaraguan and means to say so. His company, Global Premium Cigars, dates from 2011 according to its own site and 2012 according to the trade press — a one-year gap this entry leaves open.

It has no factory, and does not hide it: its cigars are rolled at Plasencia, in Estelí, the factory whose entry this atlas carries and which also rolls Crux and Blanco. One house in three on this list goes through Plasencia; that is the measure of the family''s role in the boutique scene.

The catalogue is arranged by stones and metals — Emerald, Ruby, Black Gold — with an XO above and a plain Nicaragua. The Nicaraguan classification is beyond debate: founder, leaf and workshop are all there.',
        '[{"name":"1502 Emerald","color":"#2E6B4A","force":"Medium","wrapper":"Undisclosed","vitolas":[],"story":"The emerald — the entry line, by colour."},{"name":"1502 Ruby","color":"#8B1A1A","force":"Medium-Full","wrapper":"Undisclosed","vitolas":[],"story":"The ruby."},{"name":"1502 Black Gold","color":"#2E2E2E","force":"Full","wrapper":"Undisclosed","vitolas":[],"story":"Black gold — the fullest of the three."}]',
        '1502 es el año en que Cristóbal Colón toca la costa de Nicaragua, y Enrique Sánchez Icaza lo tomó como nombre porque es nicaragüense y quiere decirlo. Su empresa, Global Premium Cigars, data de 2011 según su propio sitio y de 2012 según la prensa del oficio — un año de diferencia que esta ficha deja abierto.

No tiene fábrica, y no lo oculta: sus puros se lían en Plasencia, en Estelí, la fábrica cuya ficha lleva este atlas y que lía también Crux y Blanco. Una casa de cada tres de esta lista pasa por Plasencia; esa es la medida del papel de esta familia en la escena boutique.

El catálogo se ordena por piedras y metales — Emerald, Ruby, Black Gold — con un XO por encima y un Nicaragua a secas. La clasificación en Nicaragua no se discute: el fundador, la hoja y el taller están allí.',
        '[{"name":"1502 Emerald","color":"#2E6B4A","force":"Medium","wrapper":"No divulgada","vitolas":[],"story":"La esmeralda — la línea de entrada, por el color."},{"name":"1502 Ruby","color":"#8B1A1A","force":"Medium-Full","wrapper":"No divulgada","vitolas":[],"story":"El rubí."},{"name":"1502 Black Gold","color":"#2E2E2E","force":"Full","wrapper":"No divulgada","vitolas":[],"story":"El oro negro — el más fuerte de los tres."}]',
        '1502 ist das Jahr, in dem Christoph Kolumbus die Küste Nicaraguas berührte, und Enrique Sánchez Icaza nahm es als Namen, weil er Nicaraguaner ist und das sagen will. Seine Firma, Global Premium Cigars, stammt laut eigener Website von 2011 und laut Fachpresse von 2012 — ein Jahr Abstand, das dieser Eintrag offen lässt.

Sie hat keine Fabrik und verbirgt es nicht: Ihre Zigarren werden bei Plasencia in Estelí gerollt, der Fabrik, deren Eintrag dieser Atlas führt und die auch Crux und Blanco rollt. Jedes dritte Haus dieser Liste geht über Plasencia; das ist das Maß der Rolle dieser Familie in der Boutique-Szene.

Der Katalog ist nach Steinen und Metallen geordnet — Emerald, Ruby, Black Gold — mit einem XO darüber und einem schlichten Nicaragua. Die Einordnung in Nicaragua steht außer Frage: Gründer, Blatt und Werkstatt sind alle dort.',
        '[{"name":"1502 Emerald","color":"#2E6B4A","force":"Medium","wrapper":"Nicht angegeben","vitolas":[],"story":"Der Smaragd — die Einstiegslinie, nach Farbe."},{"name":"1502 Ruby","color":"#8B1A1A","force":"Medium-Full","wrapper":"Nicht angegeben","vitolas":[],"story":"Der Rubin."},{"name":"1502 Black Gold","color":"#2E2E2E","force":"Full","wrapper":"Nicht angegeben","vitolas":[],"story":"Schwarzes Gold — die kräftigste der drei."}]',
        '1502年是哥伦布抵达尼加拉瓜海岸的年份，恩里克·桑切斯·伊卡萨以此为名，因为他是尼加拉瓜人，并且要把这一点说出来。他的公司 Global Premium Cigars 据其官网创于2011年，据行业媒体为2012年——相差一年，本词条存而不论。

它没有工厂，也不掩饰：雪茄在埃斯特利的普拉森西亚厂卷制，本图集载有该厂词条，Crux 与 Blanco 也在那里卷制。这份名单上每三家便有一家经由普拉森西亚——这正是这个家族在精品雪茄界分量的度量。

目录以宝石与金属排列——Emerald、Ruby、Black Gold——上有 XO，另有一款朴素的 Nicaragua。归入尼加拉瓜毫无争议：创始人、烟叶与作坊都在那里。',
        '[{"name":"1502 Emerald","color":"#2E6B4A","force":"Medium","wrapper":"未公开","vitolas":[],"story":"祖母绿——按颜色排序的入门款。"},{"name":"1502 Ruby","color":"#8B1A1A","force":"Medium-Full","wrapper":"未公开","vitolas":[],"story":"红宝石。"},{"name":"1502 Black Gold","color":"#2E2E2E","force":"Full","wrapper":"未公开","vitolas":[],"story":"黑金——三者中最浓的一款。"}]',
        '1502 هي السنة التي لامس فيها كريستوفر كولومبوس ساحل نيكاراغوا، واتّخذها إنريكه سانشيس إيكاسا اسمًا لأنّه نيكاراغوي ويريد قول ذلك. تعود شركته، Global Premium Cigars، إلى 2011 بحسب موقعها وإلى 2012 بحسب صحافة المهنة — فارق سنة تتركه هذه البطاقة مفتوحًا.

ليس لها مصنع، ولا تخفي ذلك: سيجاراتها تُلفّ لدى بلاسينسيا في إستيلي، المصنع الذي يحمل هذا الأطلس بطاقته والذي يلفّ أيضًا Crux وBlanco. دارٌ من كلّ ثلاث في هذه القائمة تمرّ عبر بلاسينسيا؛ وذلك مقياس دور هذه العائلة في مشهد البوتيك.

الكتالوج مرتّب بالأحجار والمعادن — Emerald وRuby وBlack Gold — مع XO فوقها وNicaragua بسيط. والتصنيف في نيكاراغوا لا جدال فيه: المؤسّس والورقة والورشة كلّها هناك.',
        '[{"name":"1502 Emerald","color":"#2E6B4A","force":"Medium","wrapper":"غير معلن","vitolas":[],"story":"الزمرّد — خطّ الدخول، باللون."},{"name":"1502 Ruby","color":"#8B1A1A","force":"Medium-Full","wrapper":"غير معلن","vitolas":[],"story":"الياقوت."},{"name":"1502 Black Gold","color":"#2E2E2E","force":"Full","wrapper":"غير معلن","vitolas":[],"story":"الذهب الأسود — الأقوى بين الثلاثة."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

-- ── Crux Cigars (nicaragua) ──

INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Crux Cigars',
        'nicaragua',
        '2014 — Minnesota ; chez Plasencia',
        'Sans usine — Plasencia Cigars S.A., Estelí',
        'cigardojo.com et stogieguys.com (fondée en 2014 par Joel Rodgers et Jeff Haugen, co-propriétaires d''une boutique de cigares du Minnesota ; Guild et Bull & Bear roulés chez Plasencia à Estelí) ; cruxcigars.com (Epicure, Epicure Habano, Epicure Maduro, Bull & Bear, Guild, Passport, Limitada, Du Connoisseur, Marblehead) ; neptunecigar.com',
        'Crux est née dans une boutique de cigares du Minnesota, pas dans une plantation. Joel Rodgers et Jeff Haugen en étaient les co-propriétaires ; en 2014, ils sont passés de l''autre côté du comptoir et ont créé leur marque. C''est un chemin que l''atlas voit souvent — Sindicato l''a pris en groupe, Crux l''a pris à deux.

Les cigares sont roulés chez Plasencia, à Estelí, sous l''œil de Nestor Plasencia, dont l''atlas porte la fiche. Crux n''a jamais eu d''usine et ne le prétend pas : ce qu''elle apporte, c''est le choix des assemblages et l''habitude du comptoir — savoir ce qu''un amateur demande, parce qu''on le lui a vendu pendant des années.

Le catalogue est large pour une maison de cette taille : Epicure et ses déclinaisons Habano et Maduro, Bull & Bear, Guild, Passport, Limitada, Du Connoisseur, Marblehead. Une marque de détaillants devenue marque, roulée dans une des grandes fabriques du Nicaragua.',
        '[{"name":"Epicure","color":"#6B4226","force":"Medium","wrapper":"Non divulguée","vitolas":[],"story":"La ligne centrale, en trois capes — naturelle, Habano, Maduro."},{"name":"Bull & Bear","color":"#4A3728","force":"Medium-Full","wrapper":"Non divulguée","vitolas":[],"story":"Le taureau et l''ours de la Bourse — roulé chez Plasencia."},{"name":"Guild","color":"#8B5A2B","force":"Full","wrapper":"Non divulguée","vitolas":[],"story":"La guilde — sous l''œil de Nestor Plasencia."}]',
        'Crux was born in a Minnesota cigar shop, not on a plantation. Joel Rodgers and Jeff Haugen were its co-owners; in 2014 they crossed to the other side of the counter and created their brand. It is a path this atlas often sees — Sindicato took it as a group, Crux took it as a pair.

The cigars are rolled at Plasencia, in Estelí, under the eye of Nestor Plasencia, whose entry this atlas carries. Crux never had a factory and does not claim one: what it brings is the choice of blends and the habit of the counter — knowing what an enthusiast asks for, because one sold it to him for years.

The catalogue is wide for a house of this size: Epicure and its Habano and Maduro variants, Bull & Bear, Guild, Passport, Limitada, Du Connoisseur, Marblehead. A retailers'' brand become a brand, rolled in one of Nicaragua''s great factories.',
        '[{"name":"Epicure","color":"#6B4226","force":"Medium","wrapper":"Undisclosed","vitolas":[],"story":"The central line, in three wrappers — natural, Habano, Maduro."},{"name":"Bull & Bear","color":"#4A3728","force":"Medium-Full","wrapper":"Undisclosed","vitolas":[],"story":"The bull and the bear of the stock market — rolled at Plasencia."},{"name":"Guild","color":"#8B5A2B","force":"Full","wrapper":"Undisclosed","vitolas":[],"story":"The guild — under the eye of Nestor Plasencia."}]',
        'Crux nació en una tienda de puros de Minnesota, no en una plantación. Joel Rodgers y Jeff Haugen eran sus copropietarios; en 2014 pasaron al otro lado del mostrador y crearon su marca. Es un camino que este atlas ve a menudo — Sindicato lo tomó en grupo, Crux lo tomó de a dos.

Los puros se lían en Plasencia, en Estelí, bajo la mirada de Nestor Plasencia, cuya ficha lleva este atlas. Crux nunca tuvo fábrica y no lo pretende: lo que aporta es la elección de las ligadas y el hábito del mostrador — saber qué pide un aficionado, porque se le vendió durante años.

El catálogo es amplio para una casa de este tamaño: Epicure y sus variantes Habano y Maduro, Bull & Bear, Guild, Passport, Limitada, Du Connoisseur, Marblehead. Una marca de minoristas convertida en marca, liada en una de las grandes fábricas de Nicaragua.',
        '[{"name":"Epicure","color":"#6B4226","force":"Medium","wrapper":"No divulgada","vitolas":[],"story":"La línea central, en tres capas — natural, Habano, Maduro."},{"name":"Bull & Bear","color":"#4A3728","force":"Medium-Full","wrapper":"No divulgada","vitolas":[],"story":"El toro y el oso de la Bolsa — liado en Plasencia."},{"name":"Guild","color":"#8B5A2B","force":"Full","wrapper":"No divulgada","vitolas":[],"story":"El gremio — bajo la mirada de Nestor Plasencia."}]',
        'Crux entstand in einem Zigarrenladen in Minnesota, nicht auf einer Plantage. Joel Rodgers und Jeff Haugen waren seine Mitinhaber; 2014 wechselten sie auf die andere Seite des Tresens und schufen ihre Marke. Es ist ein Weg, den dieser Atlas oft sieht — Sindicato ging ihn als Gruppe, Crux zu zweit.

Die Zigarren werden bei Plasencia in Estelí gerollt, unter den Augen von Nestor Plasencia, dessen Eintrag dieser Atlas führt. Crux hatte nie eine Fabrik und behauptet es auch nicht: Was es mitbringt, ist die Wahl der Blends und die Gewohnheit des Tresens — zu wissen, was ein Liebhaber verlangt, weil man es ihm jahrelang verkauft hat.

Der Katalog ist breit für ein Haus dieser Größe: Epicure mit den Varianten Habano und Maduro, Bull & Bear, Guild, Passport, Limitada, Du Connoisseur, Marblehead. Eine Händlermarke, die Marke wurde, gerollt in einer der großen Fabriken Nicaraguas.',
        '[{"name":"Epicure","color":"#6B4226","force":"Medium","wrapper":"Nicht angegeben","vitolas":[],"story":"Die zentrale Linie, in drei Deckblättern — natur, Habano, Maduro."},{"name":"Bull & Bear","color":"#4A3728","force":"Medium-Full","wrapper":"Nicht angegeben","vitolas":[],"story":"Bulle und Bär der Börse — bei Plasencia gerollt."},{"name":"Guild","color":"#8B5A2B","force":"Full","wrapper":"Nicht angegeben","vitolas":[],"story":"Die Gilde — unter den Augen von Nestor Plasencia."}]',
        'Crux 诞生于明尼苏达州的一家雪茄店，而非种植园。乔尔·罗杰斯与杰夫·豪根是店的共有人；2014年他们走到柜台的另一边，创立了自己的牌子。这是本图集常见的路——Sindicato 是一群人走的，Crux 是两个人走的。

雪茄在埃斯特利的普拉森西亚厂卷制，由内斯托尔·普拉森西亚把关，本图集载有其词条。Crux 从未有过工厂，也不这么声称：它带来的是配方的取舍与柜台的经验——知道爱好者要什么，因为卖了他们多年。

以这种规模的公司而言，目录颇宽：Epicure 及其 Habano、Maduro 变体，Bull & Bear、Guild、Passport、Limitada、Du Connoisseur、Marblehead。一个零售商的牌子成了品牌，在尼加拉瓜的大厂之一卷制。',
        '[{"name":"Epicure","color":"#6B4226","force":"Medium","wrapper":"未公开","vitolas":[],"story":"核心系列，三种茄衣——自然、Habano、Maduro。"},{"name":"Bull & Bear","color":"#4A3728","force":"Medium-Full","wrapper":"未公开","vitolas":[],"story":"股市的牛与熊——在普拉森西亚卷制。"},{"name":"Guild","color":"#8B5A2B","force":"Full","wrapper":"未公开","vitolas":[],"story":"行会——由内斯托尔·普拉森西亚把关。"}]',
        'وُلدت كروكس في متجر سيجار بولاية مينيسوتا، لا في مزرعة. كان جويل رودجرز وجيف هوغن شريكين في ملكيّته؛ وفي 2014 عبرا إلى الجانب الآخر من المنضدة وأنشآ علامتهما. وهي طريق كثيرًا ما يراها هذا الأطلس — سلكتها Sindicato جماعةً، وسلكتها Crux اثنين.

تُلفّ السيجارات لدى بلاسينسيا في إستيلي، تحت عين نستور بلاسينسيا الذي يحمل هذا الأطلس بطاقته. لم يكن لكروكس مصنع قطّ ولا تدّعيه: ما تجلبه هو اختيار المزجات وعادة المنضدة — معرفة ما يطلبه الهاوي، لأنّه بِيع له سنوات.

والكتالوج واسع لدارٍ بهذا الحجم: Epicure وتنويعاته Habano وMaduro، وBull & Bear وGuild وPassport وLimitada وDu Connoisseur وMarblehead. علامةُ تجّار صارت علامة، تُلفّ في أحد مصانع نيكاراغوا الكبرى.',
        '[{"name":"Epicure","color":"#6B4226","force":"Medium","wrapper":"غير معلن","vitolas":[],"story":"الخطّ المركزي، بثلاثة أغلفة — طبيعي، وهابانو، ومادورو."},{"name":"Bull & Bear","color":"#4A3728","force":"Medium-Full","wrapper":"غير معلن","vitolas":[],"story":"ثور البورصة ودبّها — يُلفّ لدى بلاسينسيا."},{"name":"Guild","color":"#8B5A2B","force":"Full","wrapper":"غير معلن","vitolas":[],"story":"النقابة — تحت عين نستور بلاسينسيا."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

-- ── Blanco Cigars (nicaragua) ──

INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Blanco Cigars',
        'nicaragua',
        '1998 — Seminole, Floride ; chez Plasencia',
        'Sans usine — Plasencia Cigars S.A., Estelí ; les Plasencia sont les cousins de la famille',
        'blancocigars.com « History » et neptunecigar.com « About Blanco Cigars » (fondée en 1998 par Cesar A. Blanco, son frère Francisco et son fils David, sur les bases posées par Cesar Sr. au début des années 1900 ; famille de Pinar del Río, cousins des Plasencia depuis quatre-vingts ans ; roulée au Nicaragua chez Plasencia, qui tient culture et fabrication à Danlí et à Estelí ; David Blanco assembleur ; Liga Exclusiva de Familia, l''ancienne ligne privée des frères, en Connecticut pour Cesar et en Pennsylvania Broadleaf Maduro pour David ; Nine) ; yelp.com (boutique à Seminole, Floride)',
        'Blanco est une affaire de cousins. La famille vient de Pinar del Río, la province du tabac cubain, et elle y était voisine des Plasencia — les deux familles se connaissent depuis quatre-vingts ans, disent les Blanco, et ce sont aujourd''hui les Plasencia qui roulent leurs cigares, à Estelí. L''atlas la classe donc au Nicaragua, là où la feuille devient cigare ; le comptoir, lui, est à Seminole, en Floride.

La société date de 1998. Cesar A. Blanco l''a fondée avec son frère Francisco et son fils David, en reprenant ce que Cesar Sr. avait posé au début des années 1900. David Blanco est l''assembleur : c''est lui qui compose, et c''est chez les cousins qu''on roule, dans des fabriques qui tiennent culture et manufacture d''un bout à l''autre, à Danlí comme à Estelí.

La ligne qui dit le mieux la maison s''appelle Liga Exclusiva de Familia — l''assemblage exclusif de la famille. C''était la réserve privée des frères avant d''être vendue, et elle existe en deux versions qui sont deux tempéraments : Cesar préfère le Connecticut Shade, crémeux ; David le Pennsylvania Broadleaf Maduro, plus rude. Blanco Nine est l''autre nom que les amateurs connaissent.',
        '[{"name":"Liga Exclusiva de Familia","color":"#6B4226","force":"Medium","wrapper":"Connecticut Shade ou Pennsylvania Broadleaf Maduro","vitolas":[],"story":"L''ancienne réserve privée des frères, en deux tempéraments — le Connecticut de Cesar, le Maduro de David."},{"name":"Blanco Nine","color":"#4A3728","force":"Full","wrapper":"Non divulguée","vitolas":[],"story":"L''autre nom que les amateurs connaissent."}]',
        'Blanco is a matter of cousins. The family comes from Pinar del Río, Cuba''s tobacco province, where it was neighbour to the Plasencias — the two families have known each other for eighty years, the Blancos say, and today it is the Plasencias who roll their cigars, in Estelí. This atlas therefore classifies it in Nicaragua, where leaf becomes cigar; the counter is in Seminole, Florida.

The company dates from 1998. Cesar A. Blanco founded it with his brother Francisco and his son David, picking up what Cesar Sr. had laid down in the early 1900s. David Blanco is the blender: he composes, and the cousins roll, in factories that hold growing and manufacture end to end, in Danlí as in Estelí.

The line that says the house best is called Liga Exclusiva de Familia — the family''s exclusive blend. It was the brothers'' private reserve before it was sold, and it comes in two versions that are two temperaments: Cesar prefers Connecticut Shade, creamy; David the Pennsylvania Broadleaf Maduro, rougher. Blanco Nine is the other name enthusiasts know.',
        '[{"name":"Liga Exclusiva de Familia","color":"#6B4226","force":"Medium","wrapper":"Connecticut Shade or Pennsylvania Broadleaf Maduro","vitolas":[],"story":"The brothers'' former private reserve, in two temperaments — Cesar''s Connecticut, David''s Maduro."},{"name":"Blanco Nine","color":"#4A3728","force":"Full","wrapper":"Undisclosed","vitolas":[],"story":"The other name enthusiasts know."}]',
        'Blanco es un asunto de primos. La familia viene de Pinar del Río, la provincia del tabaco cubano, donde era vecina de los Plasencia — las dos familias se conocen desde hace ochenta años, dicen los Blanco, y hoy son los Plasencia quienes lían sus puros, en Estelí. Este atlas la clasifica pues en Nicaragua, donde la hoja se vuelve puro; el mostrador está en Seminole, Florida.

La empresa data de 1998. Cesar A. Blanco la fundó con su hermano Francisco y su hijo David, retomando lo que Cesar Sr. había sentado a principios del siglo XX. David Blanco es el ligador: él compone, y en casa de los primos se lía, en fábricas que sostienen cultivo y manufactura de punta a punta, en Danlí como en Estelí.

La línea que mejor dice la casa se llama Liga Exclusiva de Familia. Era la reserva privada de los hermanos antes de venderse, y existe en dos versiones que son dos temperamentos: Cesar prefiere el Connecticut Shade, cremoso; David el Pennsylvania Broadleaf Maduro, más rudo. Blanco Nine es el otro nombre que los aficionados conocen.',
        '[{"name":"Liga Exclusiva de Familia","color":"#6B4226","force":"Medium","wrapper":"Connecticut Shade o Pennsylvania Broadleaf Maduro","vitolas":[],"story":"La antigua reserva privada de los hermanos, en dos temperamentos — el Connecticut de Cesar, el Maduro de David."},{"name":"Blanco Nine","color":"#4A3728","force":"Full","wrapper":"No divulgada","vitolas":[],"story":"El otro nombre que los aficionados conocen."}]',
        'Blanco ist eine Sache von Cousins. Die Familie stammt aus Pinar del Río, Kubas Tabakprovinz, wo sie Nachbarin der Plasencias war — die beiden Familien kennen sich seit achtzig Jahren, sagen die Blancos, und heute sind es die Plasencias, die ihre Zigarren rollen, in Estelí. Dieser Atlas ordnet sie daher in Nicaragua ein, wo das Blatt zur Zigarre wird; der Tresen steht in Seminole, Florida.

Die Firma stammt von 1998. Cesar A. Blanco gründete sie mit seinem Bruder Francisco und seinem Sohn David und nahm auf, was Cesar Sr. Anfang des 20. Jahrhunderts gelegt hatte. David Blanco ist der Blender: Er komponiert, und bei den Cousins wird gerollt, in Fabriken, die Anbau und Fertigung von einem Ende zum anderen halten, in Danlí wie in Estelí.

Die Linie, die das Haus am besten sagt, heißt Liga Exclusiva de Familia — der exklusive Blend der Familie. Sie war die Privatreserve der Brüder, bevor sie verkauft wurde, und es gibt sie in zwei Versionen, die zwei Temperamente sind: Cesar bevorzugt Connecticut Shade, cremig; David das Pennsylvania Broadleaf Maduro, rauer. Blanco Nine ist der andere Name, den Liebhaber kennen.',
        '[{"name":"Liga Exclusiva de Familia","color":"#6B4226","force":"Medium","wrapper":"Connecticut Shade oder Pennsylvania Broadleaf Maduro","vitolas":[],"story":"Die ehemalige Privatreserve der Brüder, in zwei Temperamenten — Cesars Connecticut, Davids Maduro."},{"name":"Blanco Nine","color":"#4A3728","force":"Full","wrapper":"Nicht angegeben","vitolas":[],"story":"Der andere Name, den Liebhaber kennen."}]',
        'Blanco 是一桩表亲之间的事。家族来自古巴烟草大省比那尔德里奥，在那里与普拉森西亚家族比邻——布兰科家说两家相识已八十年，如今正是普拉森西亚家在埃斯特利为他们卷制雪茄。本图集因此把它归入尼加拉瓜——烟叶成为雪茄之处；柜台则在佛罗里达州塞米诺尔。

公司创于1998年。塞萨尔·A·布兰科与兄弟弗朗西斯科、儿子戴维共同创办，接续老塞萨尔在二十世纪初奠定的基业。戴维·布兰科是调配师：他调配，表亲们卷制——在丹利与埃斯特利那些从种植到制造一以贯之的工厂里。

最能说明这家的系列叫 Liga Exclusiva de Familia——家族专属配方。它原是兄弟俩的私藏，后来才出售，有两个版本、两种性情：塞萨尔偏爱奶油般的康涅狄格阴植茄衣，戴维偏爱更粗犷的宾夕法尼亚阔叶马杜罗。Blanco Nine 是爱好者知道的另一个名字。',
        '[{"name":"Liga Exclusiva de Familia","color":"#6B4226","force":"Medium","wrapper":"康涅狄格阴植或宾夕法尼亚阔叶马杜罗","vitolas":[],"story":"兄弟俩昔日的私藏，两种性情——塞萨尔的康涅狄格，戴维的马杜罗。"},{"name":"Blanco Nine","color":"#4A3728","force":"Full","wrapper":"未公开","vitolas":[],"story":"爱好者知道的另一个名字。"}]',
        'بلانكو شأنُ أبناء عمومة. تأتي العائلة من بينار ديل ريو، مقاطعة التبغ الكوبية، حيث كانت جارةً لآل بلاسينسيا — تتعارف العائلتان منذ ثمانين سنة، كما يقول آل بلانكو، وآل بلاسينسيا هم اليوم من يلفّون سيجاراتهم في إستيلي. لذلك يصنّفها هذا الأطلس في نيكاراغوا، حيث تصير الورقة سيجارًا؛ أمّا المنضدة ففي سيمينول بفلوريدا.

تعود الشركة إلى 1998. أسّسها سيزار أ. بلانكو مع أخيه فرانسيسكو وابنه ديفيد، مستأنفًا ما أرساه سيزار الأب في مطلع القرن العشرين. وديفيد بلانكو هو المزّاج: هو يركّب، وعند أبناء العمومة يُلفّ، في مصانع تمسك الزراعة والصنع من طرف إلى طرف، في دانلي كما في إستيلي.

والخطّ الذي يقول الدار على أفضل وجه اسمه Liga Exclusiva de Familia — مزجة العائلة الحصرية. كانت الاحتياطي الخاص للأخوين قبل أن تُباع، وهي بنسختين هما مزاجان: يفضّل سيزار الكونيتيكت الظليل الكريمي؛ ويفضّل ديفيد مادورو بنسلفانيا العريض الورق الأخشن. وBlanco Nine هو الاسم الآخر الذي يعرفه الهواة.',
        '[{"name":"Liga Exclusiva de Familia","color":"#6B4226","force":"Medium","wrapper":"كونيتيكت ظليل أو مادورو بنسلفانيا","vitolas":[],"story":"الاحتياطي الخاص السابق للأخوين، بمزاجين — كونيتيكت سيزار، ومادورو ديفيد."},{"name":"Blanco Nine","color":"#4A3728","force":"Full","wrapper":"غير معلن","vitolas":[],"story":"الاسم الآخر الذي يعرفه الهواة."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

-- ── Debonaire House (dominican) ──

INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Debonaire House',
        'dominican',
        '2012 — Phil Zanghi ; chez De Los Reyes',
        'Sans usine — De Los Reyes Cigars, Santiago, sous la supervision de Phil Zanghi',
        'cigar-coop.com « Spotlight on Debonaire House at the 2018 IPCPR » et « Debonaire Daybreak » (Debonaire House réunit deux marques, Debonaire et Indian Motorcycle Cigars ; Habano et Maduro pour chacune, puis Daybreak en Connecticut d''Équateur, cinquième assemblage) ; halfwheel.com PCA 2021 et 2025 (Phil Zanghi, fondation en 2012 avec Daniel Sinclair ; produite chez De Los Reyes sous la supervision de Zanghi) ; stogiepress.com (distribution du Daybreak avec Drew Estate) ; tobaccobusiness.com « The Power of Positivity »',
        'Debonaire House est une maison à deux marques et sans usine. Phil Zanghi l''a fondée en 2012 avec Daniel Sinclair, à partir d''une relation ancienne avec Emilio Reyes et la fabrique De Los Reyes, à Santiago, dont l''atlas porte la fiche : c''est là que tout est roulé, sous la supervision de Zanghi, et la fiche De Los Reyes le nommait déjà comme travail à façon sans que la maison ait la sienne.

Les deux marques sont Debonaire — le nom de la maison — et Indian Motorcycle Cigars, sous licence du constructeur de motos. Chacune est venue en deux capes, Habano et Maduro ; en 2018, Daybreak a ajouté un Connecticut d''Équateur sous le nom Debonaire, cinquième assemblage du catalogue, distribué avec Drew Estate.

Le modèle est celui de la scène boutique : une signature américaine, une fabrique dominicaine, et l''atlas qui nomme les deux.',
        '[{"name":"Debonaire Habano","color":"#8B5A2B","force":"Medium-Full","wrapper":"Habano","vitolas":[],"story":"L''une des deux capes de départ."},{"name":"Debonaire Daybreak","color":"#C9A96E","force":"Medium","wrapper":"Connecticut d''Équateur","vitolas":[],"story":"Le cinquième assemblage, en 2018, distribué avec Drew Estate."},{"name":"Indian Motorcycle","color":"#7A2E1E","force":"Medium-Full","wrapper":"Non divulguée","vitolas":[],"story":"La seconde marque de la maison, sous licence du constructeur de motos. Habano et Maduro."}]',
        'Debonaire House is a two-brand house without a factory. Phil Zanghi founded it in 2012 with Daniel Sinclair, out of an old relationship with Emilio Reyes and the De Los Reyes factory in Santiago, whose entry this atlas carries: that is where everything is rolled, under Zanghi''s supervision, and the De Los Reyes entry already named it as contract work without the house having its own.

The two brands are Debonaire — the house''s name — and Indian Motorcycle Cigars, under licence from the motorcycle maker. Each came in two wrappers, Habano and Maduro; in 2018, Daybreak added an Ecuadorian Connecticut under the Debonaire name, the catalogue''s fifth blend, distributed with Drew Estate.

The model is the boutique scene''s: an American signature, a Dominican factory, and this atlas naming both.',
        '[{"name":"Debonaire Habano","color":"#8B5A2B","force":"Medium-Full","wrapper":"Habano","vitolas":[],"story":"One of the two original wrappers."},{"name":"Debonaire Daybreak","color":"#C9A96E","force":"Medium","wrapper":"Ecuadorian Connecticut","vitolas":[],"story":"The fifth blend, in 2018, distributed with Drew Estate."},{"name":"Indian Motorcycle","color":"#7A2E1E","force":"Medium-Full","wrapper":"Undisclosed","vitolas":[],"story":"The house''s second brand, under licence from the motorcycle maker. Habano and Maduro."}]',
        'Debonaire House es una casa de dos marcas y sin fábrica. Phil Zanghi la fundó en 2012 con Daniel Sinclair, a partir de una antigua relación con Emilio Reyes y la fábrica De Los Reyes, en Santiago, cuya ficha lleva este atlas: allí se lía todo, bajo la supervisión de Zanghi, y la ficha De Los Reyes ya la nombraba como trabajo a maquila sin que la casa tuviera la suya.

Las dos marcas son Debonaire — el nombre de la casa — e Indian Motorcycle Cigars, bajo licencia del fabricante de motos. Cada una vino en dos capas, Habano y Maduro; en 2018, Daybreak añadió un Connecticut de Ecuador bajo el nombre Debonaire, quinta ligada del catálogo, distribuida con Drew Estate.

El modelo es el de la escena boutique: una firma estadounidense, una fábrica dominicana, y este atlas que nombra a ambas.',
        '[{"name":"Debonaire Habano","color":"#8B5A2B","force":"Medium-Full","wrapper":"Habano","vitolas":[],"story":"Una de las dos capas de origen."},{"name":"Debonaire Daybreak","color":"#C9A96E","force":"Medium","wrapper":"Connecticut de Ecuador","vitolas":[],"story":"La quinta ligada, en 2018, distribuida con Drew Estate."},{"name":"Indian Motorcycle","color":"#7A2E1E","force":"Medium-Full","wrapper":"No divulgada","vitolas":[],"story":"La segunda marca de la casa, bajo licencia del fabricante de motos. Habano y Maduro."}]',
        'Debonaire House ist ein Haus mit zwei Marken und ohne Fabrik. Phil Zanghi gründete es 2012 mit Daniel Sinclair, aus einer alten Beziehung zu Emilio Reyes und der Fabrik De Los Reyes in Santiago, deren Eintrag dieser Atlas führt: Dort wird alles gerollt, unter Zanghis Aufsicht, und der De-Los-Reyes-Eintrag nannte es bereits als Lohnfertigung, ohne dass das Haus einen eigenen hatte.

Die beiden Marken sind Debonaire — der Name des Hauses — und Indian Motorcycle Cigars, unter Lizenz des Motorradherstellers. Jede kam in zwei Deckblättern, Habano und Maduro; 2018 fügte Daybreak ein ecuadorianisches Connecticut unter dem Namen Debonaire hinzu, den fünften Blend des Katalogs, vertrieben mit Drew Estate.

Das Modell ist das der Boutique-Szene: eine amerikanische Signatur, eine dominikanische Fabrik, und dieser Atlas, der beide nennt.',
        '[{"name":"Debonaire Habano","color":"#8B5A2B","force":"Medium-Full","wrapper":"Habano","vitolas":[],"story":"Eines der zwei ursprünglichen Deckblätter."},{"name":"Debonaire Daybreak","color":"#C9A96E","force":"Medium","wrapper":"Ecuadorianisches Connecticut","vitolas":[],"story":"Der fünfte Blend, 2018, vertrieben mit Drew Estate."},{"name":"Indian Motorcycle","color":"#7A2E1E","force":"Medium-Full","wrapper":"Nicht angegeben","vitolas":[],"story":"Die zweite Marke des Hauses, unter Lizenz des Motorradherstellers. Habano und Maduro."}]',
        'Debonaire House 是一家拥有两个品牌、没有工厂的公司。菲尔·赞吉2012年与丹尼尔·辛克莱共同创办，源于与埃米利奥·雷耶斯及圣地亚哥 De Los Reyes 工厂的旧交——本图集载有该厂词条：一切都在那里、在赞吉的监督下卷制，而 De Los Reyes 词条早已把它列为代工，只是这家公司自己还没有词条。

两个品牌是 Debonaire——公司之名——与获摩托车制造商授权的 Indian Motorcycle Cigars。各有 Habano 与 Maduro 两种茄衣；2018年，Daybreak 以 Debonaire 之名添加了厄瓜多尔康涅狄格茄衣，成为目录中的第五款配方，与 Drew Estate 联合分销。

模式是精品雪茄界的那一种：美国的署名，多米尼加的工厂，而本图集两者皆点名。',
        '[{"name":"Debonaire Habano","color":"#8B5A2B","force":"Medium-Full","wrapper":"Habano","vitolas":[],"story":"最初两种茄衣之一。"},{"name":"Debonaire Daybreak","color":"#C9A96E","force":"Medium","wrapper":"厄瓜多尔康涅狄格","vitolas":[],"story":"2018年的第五款配方，与 Drew Estate 联合分销。"},{"name":"Indian Motorcycle","color":"#7A2E1E","force":"Medium-Full","wrapper":"未公开","vitolas":[],"story":"公司的第二个品牌，获摩托车制造商授权。Habano 与 Maduro。"}]',
        'ديبونير هاوس دارٌ بعلامتين وبلا مصنع. أسّسها فيل زانغي سنة 2012 مع دانيال سنكلير، من علاقة قديمة مع إميليو رييس ومصنع De Los Reyes في سانتياغو الذي يحمل هذا الأطلس بطاقته: هناك يُلفّ كلّ شيء، تحت إشراف زانغي، وكانت بطاقة De Los Reyes تسمّيها أصلًا عملًا بالوكالة دون أن تكون للدار بطاقتها.

العلامتان هما Debonaire — اسم الدار — وIndian Motorcycle Cigars، بترخيص من صانع الدرّاجات النارية. جاءت كلٌّ منهما بغلافين، هابانو ومادورو؛ وفي 2018 أضاف Daybreak كونيتيكت إكوادوريًّا تحت اسم Debonaire، المزجة الخامسة في الكتالوج، وُزّعت مع Drew Estate.

النموذج هو نموذج مشهد البوتيك: توقيع أمريكي، ومصنع دومينيكي، وهذا الأطلس يسمّي الاثنين.',
        '[{"name":"Debonaire Habano","color":"#8B5A2B","force":"Medium-Full","wrapper":"Habano","vitolas":[],"story":"أحد الغلافين الأصليّين."},{"name":"Debonaire Daybreak","color":"#C9A96E","force":"Medium","wrapper":"كونيتيكت إكوادوري","vitolas":[],"story":"المزجة الخامسة، سنة 2018، وُزّعت مع Drew Estate."},{"name":"Indian Motorcycle","color":"#7A2E1E","force":"Medium-Full","wrapper":"غير معلن","vitolas":[],"story":"العلامة الثانية للدار، بترخيص من صانع الدرّاجات النارية. هابانو ومادورو."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

-- ── Patoro (dominican) ──

INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Patoro',
        'dominican',
        '2001 — Suisse ; chez De Los Reyes',
        'Sans usine — De Los Reyes Cigars (Augusto Reyes), Santiago',
        'patoro.com « History » et cigar-coop.com « Patoro Vintage Robusto Launched for U.S. Market at 2017 IPCPR » (Patrick J. Martin, Suisse ; vend en Europe depuis 2001 ; Gran Añejo Reserva en 2001, Platino en 2003, puis Vintage, VA, Brasil, Serie P ; la Serie P américaine diffère de l''européenne — cape et sous-cape brésiliennes, tripe dominicaine) ; cigaraficionado.com « CLE to Distribute Patoro Serie P U.S.A. Edition » (distribution américaine par C.L.E.) ; neptunecigar.com (faite à la fabrique d''Augusto Reyes) ; halfwheel.com « Patoro Platino Perfecto »',
        'Patoro est une maison suisse qui fait rouler en République dominicaine, et l''atlas la classe là où l''on roule — comme il l''a fait pour Oettinger Davidoff, Villiger et les autres maisons suisses de la migration 180. Patrick J. Martin l''a créée et vend en Europe depuis 2001 ; il a choisi la République dominicaine pour la terre, et De Los Reyes, la fabrique d''Augusto Reyes à Santiago dont l''atlas porte la fiche, pour l''atelier. Cette fiche-là la nommait déjà comme travail à façon.

Le catalogue a grandi ligne par ligne : Gran Añejo Reserva en 2001, Platino en 2003, puis Vintage, VA, Brasil et la Serie P. Le détail qui dit le métier est que la Serie P vendue aux États-Unis n''est pas celle vendue en Europe — cape et sous-cape brésiliennes sur tripe dominicaine pour l''Amérique, un autre assemblage pour le Vieux Continent. Une même bague, deux cigares, et la maison le dit.

Aux États-Unis, c''est C.L.E. — la maison de Christian Eiroa, encore lui — qui distribue l''édition américaine de la Serie P. Le nom d''Eiroa apparaît ainsi sur une septième fiche de cet atlas qui n''est pas la sienne.',
        '[{"name":"Gran Añejo Reserva","color":"#5B3A29","force":"Medium-Full","wrapper":"Non divulguée","vitolas":[],"story":"La première ligne, en 2001."},{"name":"Platino","color":"#A8A8A8","force":"Medium","wrapper":"Non divulguée","vitolas":[],"story":"Depuis 2003."},{"name":"Serie P","color":"#8B5A2B","force":"Medium-Full","wrapper":"Brésil (édition américaine)","vitolas":[],"story":"Deux cigares sous une bague : l''édition américaine, en cape et sous-cape brésiliennes, n''est pas l''européenne. Distribuée aux États-Unis par C.L.E."}]',
        'Patoro is a Swiss house that has its cigars rolled in the Dominican Republic, and this atlas classifies it where the rolling happens — as it did for Oettinger Davidoff, Villiger and the other Swiss houses of migration 180. Patrick J. Martin created it and has sold in Europe since 2001; he chose the Dominican Republic for the land, and De Los Reyes, Augusto Reyes''s factory in Santiago whose entry this atlas carries, for the workshop. That entry already named it as contract work.

The catalogue grew line by line: Gran Añejo Reserva in 2001, Platino in 2003, then Vintage, VA, Brasil and the Serie P. The detail that tells the trade is that the Serie P sold in the United States is not the one sold in Europe — Brazilian wrapper and binder over Dominican filler for America, another blend for the Old Continent. One band, two cigars, and the house says so.

In the United States, it is C.L.E. — Christian Eiroa''s house, him again — that distributes the American edition of the Serie P. The Eiroa name thus appears on a seventh entry of this atlas that is not his own.',
        '[{"name":"Gran Añejo Reserva","color":"#5B3A29","force":"Medium-Full","wrapper":"Undisclosed","vitolas":[],"story":"The first line, in 2001."},{"name":"Platino","color":"#A8A8A8","force":"Medium","wrapper":"Undisclosed","vitolas":[],"story":"Since 2003."},{"name":"Serie P","color":"#8B5A2B","force":"Medium-Full","wrapper":"Brazil (US edition)","vitolas":[],"story":"Two cigars under one band: the American edition, in Brazilian wrapper and binder, is not the European one. Distributed in the US by C.L.E."}]',
        'Patoro es una casa suiza que hace liar en la República Dominicana, y este atlas la clasifica donde se lía — como hizo con Oettinger Davidoff, Villiger y las otras casas suizas de la migración 180. Patrick J. Martin la creó y vende en Europa desde 2001; eligió la República Dominicana por la tierra, y De Los Reyes, la fábrica de Augusto Reyes en Santiago cuya ficha lleva este atlas, por el taller. Esa ficha ya la nombraba como trabajo a maquila.

El catálogo creció línea a línea: Gran Añejo Reserva en 2001, Platino en 2003, luego Vintage, VA, Brasil y la Serie P. El detalle que dice el oficio es que la Serie P vendida en Estados Unidos no es la vendida en Europa — capa y capote brasileños sobre tripa dominicana para América, otra ligada para el Viejo Continente. Una misma anilla, dos puros, y la casa lo dice.

En Estados Unidos, es C.L.E. — la casa de Christian Eiroa, otra vez él — quien distribuye la edición americana de la Serie P. El nombre de Eiroa aparece así en una séptima ficha de este atlas que no es la suya.',
        '[{"name":"Gran Añejo Reserva","color":"#5B3A29","force":"Medium-Full","wrapper":"No divulgada","vitolas":[],"story":"La primera línea, en 2001."},{"name":"Platino","color":"#A8A8A8","force":"Medium","wrapper":"No divulgada","vitolas":[],"story":"Desde 2003."},{"name":"Serie P","color":"#8B5A2B","force":"Medium-Full","wrapper":"Brasil (edición americana)","vitolas":[],"story":"Dos puros bajo una anilla: la edición americana, con capa y capote brasileños, no es la europea. Distribuida en Estados Unidos por C.L.E."}]',
        'Patoro ist ein Schweizer Haus, das in der Dominikanischen Republik rollen lässt, und dieser Atlas ordnet es dort ein, wo gerollt wird — wie bei Oettinger Davidoff, Villiger und den anderen Schweizer Häusern der Migration 180. Patrick J. Martin gründete es und verkauft seit 2001 in Europa; er wählte die Dominikanische Republik wegen des Bodens und De Los Reyes, die Fabrik von Augusto Reyes in Santiago, deren Eintrag dieser Atlas führt, wegen der Werkstatt. Jener Eintrag nannte es bereits als Lohnfertigung.

Der Katalog wuchs Linie für Linie: Gran Añejo Reserva 2001, Platino 2003, dann Vintage, VA, Brasil und die Serie P. Das Detail, das das Metier verrät: Die in den USA verkaufte Serie P ist nicht die in Europa verkaufte — brasilianisches Deck- und Umblatt über dominikanischer Einlage für Amerika, ein anderer Blend für den alten Kontinent. Eine Banderole, zwei Zigarren, und das Haus sagt es.

In den Vereinigten Staaten vertreibt C.L.E. — das Haus von Christian Eiroa, schon wieder er — die amerikanische Ausgabe der Serie P. Der Name Eiroa erscheint damit auf einem siebten Eintrag dieses Atlas, der nicht sein eigener ist.',
        '[{"name":"Gran Añejo Reserva","color":"#5B3A29","force":"Medium-Full","wrapper":"Nicht angegeben","vitolas":[],"story":"Die erste Linie, 2001."},{"name":"Platino","color":"#A8A8A8","force":"Medium","wrapper":"Nicht angegeben","vitolas":[],"story":"Seit 2003."},{"name":"Serie P","color":"#8B5A2B","force":"Medium-Full","wrapper":"Brasilien (US-Ausgabe)","vitolas":[],"story":"Zwei Zigarren unter einer Banderole: Die amerikanische Ausgabe mit brasilianischem Deck- und Umblatt ist nicht die europäische. In den USA von C.L.E. vertrieben."}]',
        'Patoro 是一家在多米尼加共和国委托卷制的瑞士公司，本图集按卷制地归类——正如对奥廷格大卫杜夫、维利格及迁移180中其他瑞士公司的处理。帕特里克·J·马丁创立了它，自2001年起在欧洲销售；他为土地选择了多米尼加共和国，为作坊选择了圣地亚哥奥古斯托·雷耶斯的工厂 De Los Reyes——本图集载有该厂词条，且该词条早已把它列为代工。

目录逐线增长：2001年 Gran Añejo Reserva，2003年 Platino，随后 Vintage、VA、Brasil 与 Serie P。道出行业门道的细节是：在美国销售的 Serie P 与欧洲的不是同一款——美国版为巴西茄衣与茄套配多米尼加填充，旧大陆则是另一种配方。同一烟标，两支雪茄，公司也这么说。

在美国，负责分销 Serie P 美国版的是 C.L.E.——克里斯蒂安·埃罗亚的公司，又是他。埃罗亚之名由此出现在本图集第七个并非他自己的词条上。',
        '[{"name":"Gran Añejo Reserva","color":"#5B3A29","force":"Medium-Full","wrapper":"未公开","vitolas":[],"story":"2001年的第一条线。"},{"name":"Platino","color":"#A8A8A8","force":"Medium","wrapper":"未公开","vitolas":[],"story":"自2003年起。"},{"name":"Serie P","color":"#8B5A2B","force":"Medium-Full","wrapper":"巴西（美国版）","vitolas":[],"story":"同一烟标下的两支雪茄：巴西茄衣与茄套的美国版不同于欧洲版。美国由 C.L.E. 分销。"}]',
        'باتورو دارٌ سويسرية تُلفّ سيجاراتها في جمهورية الدومينيكان، ويصنّفها هذا الأطلس حيث يُلفّ — كما فعل مع أوتينغر دافيدوف وفيلّيغر وسائر الدور السويسرية في الهجرة 180. أنشأها باتريك ج. مارتن وتبيع في أوروبا منذ 2001؛ اختار جمهورية الدومينيكان للأرض، وDe Los Reyes، مصنعَ أوغوستو رييس في سانتياغو الذي يحمل هذا الأطلس بطاقته، للورشة. وكانت تلك البطاقة تسمّيها أصلًا عملًا بالوكالة.

كبر الكتالوج خطًّا فخطًّا: Gran Añejo Reserva سنة 2001، وPlatino سنة 2003، ثم Vintage وVA وBrasil وSerie P. والتفصيل الذي يقول المهنة أنّ Serie P المباعة في الولايات المتحدة ليست المباعة في أوروبا — غلاف ورباط برازيليان على حشوة دومينيكية لأمريكا، ومزجة أخرى للقارّة القديمة. طوقٌ واحد وسيجاران، والدار تقول ذلك.

وفي الولايات المتحدة، C.L.E. — دار كريستيان إيروا، هو مجدّدًا — هي التي توزّع الإصدار الأمريكي من Serie P. وهكذا يظهر اسم إيروا على بطاقة سابعة في هذا الأطلس ليست بطاقته.',
        '[{"name":"Gran Añejo Reserva","color":"#5B3A29","force":"Medium-Full","wrapper":"غير معلن","vitolas":[],"story":"الخطّ الأوّل، سنة 2001."},{"name":"Platino","color":"#A8A8A8","force":"Medium","wrapper":"غير معلن","vitolas":[],"story":"منذ 2003."},{"name":"Serie P","color":"#8B5A2B","force":"Medium-Full","wrapper":"البرازيل (الإصدار الأمريكي)","vitolas":[],"story":"سيجاران تحت طوق واحد: الإصدار الأمريكي، بغلاف ورباط برازيليّين، ليس الأوروبي. توزّعه C.L.E. في الولايات المتحدة."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

-- ── ADVentura (dominican) ──

INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('ADVentura',
        'dominican',
        '2016 — Henderson Ventura et Marcel Knobel',
        'Sans usine — Tabacalera William Ventura, Tamboril',
        'halfwheel.com « ADV & McKay Cigars Co. to Make IPCPR Debut with ADVentura The Conqueror » (fondée en 2016, coopération entre Henderson Ventura, de Tabacalera William Ventura, et Marcel Knobel, sommelier, producteur et détaillant de café suisse ; The Conqueror en cape Habano 2000 d''Équateur, sous-cape Sumatra d''Équateur, tripes dominicaine et nicaraguayenne ; The Explorer et The Navigator) ; adventuracigars.com (The Royal Return, Barbarroja''s Invasion, Blue Eyed Jack''s Revenge) ; smokingpipes.com',
        'ADVentura est une collaboration, et son nom l''écrit en majuscules : ADV pour l''associé, Ventura pour la fabrique. Henderson Ventura est co-maître assembleur et fils de William Ventura, dont l''atlas porte la fiche ; Marcel Knobel est suisse, sommelier, producteur et détaillant de café, venu au cigare par le goût. Ils ont créé la marque en 2016, et tout est roulé à la Tabacalera William Ventura, à Tamboril.

Le catalogue raconte des voyages et des pirates : The Explorer, The Navigator, The Conqueror — cape Habano 2000 d''Équateur, sous-cape Sumatra d''Équateur, tripes dominicaine et nicaraguayenne —, puis The Royal Return, Barbarroja''s Invasion, Blue Eyed Jack''s Revenge. Aux États-Unis, la maison est entrée au salon de 2019 sous le nom d''ADV & McKay Cigars Co.

Une marque conçue par un Suisse et un Dominicain, roulée par le second : l''atlas nomme les deux, et le pays est celui de l''atelier.',
        '[{"name":"The Conqueror","color":"#7A2E1E","force":"Medium-Full","wrapper":"Habano 2000 d''Équateur","vitolas":[],"story":"Sous-cape Sumatra d''Équateur, tripes dominicaine et nicaraguayenne. La ligne de l''entrée aux États-Unis, en 2019."},{"name":"The Explorer","color":"#5B3A29","force":"Medium","wrapper":"Non divulguée","vitolas":[],"story":"L''explorateur — avec The Navigator, les deux premières."},{"name":"Barbarroja''s Invasion","color":"#8B1A1A","force":"Full","wrapper":"Non divulguée","vitolas":[],"story":"Barberousse, le pirate. Le ton de la maison."}]',
        'ADVentura is a collaboration, and its name writes it in capitals: ADV for the partner, Ventura for the factory. Henderson Ventura is co-master blender and son of William Ventura, whose entry this atlas carries; Marcel Knobel is Swiss, a sommelier, coffee producer and retailer who came to cigars through taste. They created the brand in 2016, and everything is rolled at Tabacalera William Ventura, in Tamboril.

The catalogue tells of voyages and pirates: The Explorer, The Navigator, The Conqueror — Ecuadorian Habano 2000 wrapper, Ecuadorian Sumatra binder, Dominican and Nicaraguan fillers — then The Royal Return, Barbarroja''s Invasion, Blue Eyed Jack''s Revenge. In the United States the house entered the 2019 trade show under the name ADV & McKay Cigars Co.

A brand conceived by a Swiss and a Dominican, rolled by the latter: this atlas names both, and the country is that of the workshop.',
        '[{"name":"The Conqueror","color":"#7A2E1E","force":"Medium-Full","wrapper":"Ecuadorian Habano 2000","vitolas":[],"story":"Ecuadorian Sumatra binder, Dominican and Nicaraguan fillers. The line of the US entry, in 2019."},{"name":"The Explorer","color":"#5B3A29","force":"Medium","wrapper":"Undisclosed","vitolas":[],"story":"The explorer — with The Navigator, the first two."},{"name":"Barbarroja''s Invasion","color":"#8B1A1A","force":"Full","wrapper":"Undisclosed","vitolas":[],"story":"Barbarossa, the pirate. The tone of the house."}]',
        'ADVentura es una colaboración, y su nombre lo escribe en mayúsculas: ADV por el socio, Ventura por la fábrica. Henderson Ventura es co-maestro ligador e hijo de William Ventura, cuya ficha lleva este atlas; Marcel Knobel es suizo, sommelier, productor y minorista de café, llegado al puro por el gusto. Crearon la marca en 2016, y todo se lía en la Tabacalera William Ventura, en Tamboril.

El catálogo cuenta viajes y piratas: The Explorer, The Navigator, The Conqueror — capa Habano 2000 de Ecuador, capote Sumatra de Ecuador, tripas dominicana y nicaragüense —, luego The Royal Return, Barbarroja''s Invasion, Blue Eyed Jack''s Revenge. En Estados Unidos la casa entró en el salón de 2019 bajo el nombre ADV & McKay Cigars Co.

Una marca concebida por un suizo y un dominicano, liada por el segundo: este atlas nombra a ambos, y el país es el del taller.',
        '[{"name":"The Conqueror","color":"#7A2E1E","force":"Medium-Full","wrapper":"Habano 2000 de Ecuador","vitolas":[],"story":"Capote Sumatra de Ecuador, tripas dominicana y nicaragüense. La línea de la entrada en Estados Unidos, en 2019."},{"name":"The Explorer","color":"#5B3A29","force":"Medium","wrapper":"No divulgada","vitolas":[],"story":"El explorador — con The Navigator, las dos primeras."},{"name":"Barbarroja''s Invasion","color":"#8B1A1A","force":"Full","wrapper":"No divulgada","vitolas":[],"story":"Barbarroja, el pirata. El tono de la casa."}]',
        'ADVentura ist eine Zusammenarbeit, und der Name schreibt es in Großbuchstaben: ADV für den Partner, Ventura für die Fabrik. Henderson Ventura ist Co-Master-Blender und Sohn von William Ventura, dessen Eintrag dieser Atlas führt; Marcel Knobel ist Schweizer, Sommelier, Kaffeeproduzent und -händler, über den Geschmack zur Zigarre gekommen. Sie schufen die Marke 2016, und alles wird in der Tabacalera William Ventura in Tamboril gerollt.

Der Katalog erzählt von Reisen und Piraten: The Explorer, The Navigator, The Conqueror — ecuadorianisches Habano-2000-Deckblatt, ecuadorianisches Sumatra-Umblatt, dominikanische und nicaraguanische Einlage —, dann The Royal Return, Barbarroja''s Invasion, Blue Eyed Jack''s Revenge. In den Vereinigten Staaten trat das Haus 2019 unter dem Namen ADV & McKay Cigars Co. auf der Messe an.

Eine Marke, ersonnen von einem Schweizer und einem Dominikaner, gerollt vom Letzteren: Dieser Atlas nennt beide, und das Land ist das der Werkstatt.',
        '[{"name":"The Conqueror","color":"#7A2E1E","force":"Medium-Full","wrapper":"Ecuadorianisches Habano 2000","vitolas":[],"story":"Ecuadorianisches Sumatra-Umblatt, dominikanische und nicaraguanische Einlage. Die Linie des US-Eintritts 2019."},{"name":"The Explorer","color":"#5B3A29","force":"Medium","wrapper":"Nicht angegeben","vitolas":[],"story":"Der Entdecker — mit The Navigator die ersten zwei."},{"name":"Barbarroja''s Invasion","color":"#8B1A1A","force":"Full","wrapper":"Nicht angegeben","vitolas":[],"story":"Barbarossa, der Pirat. Der Ton des Hauses."}]',
        'ADVentura 是一场合作，名字以大写写明：ADV 代表合伙人，Ventura 代表工厂。亨德森·文图拉是联合调配大师、威廉·文图拉之子——本图集载有其父词条；马塞尔·克诺贝尔是瑞士人，侍酒师、咖啡生产者与零售商，因味觉而入雪茄之门。两人于2016年创立品牌，一切都在坦博里尔的 Tabacalera William Ventura 卷制。

目录讲述航海与海盗：The Explorer、The Navigator、The Conqueror——厄瓜多尔 Habano 2000 茄衣、厄瓜多尔苏门答腊茄套、多米尼加与尼加拉瓜填充——继而 The Royal Return、Barbarroja''s Invasion、Blue Eyed Jack''s Revenge。在美国，公司以 ADV & McKay Cigars Co. 之名于2019年展会登场。

一个瑞士人与一个多米尼加人构思、由后者卷制的牌子：本图集两者皆点名，而国家是作坊所在之国。',
        '[{"name":"The Conqueror","color":"#7A2E1E","force":"Medium-Full","wrapper":"厄瓜多尔 Habano 2000","vitolas":[],"story":"厄瓜多尔苏门答腊茄套，多米尼加与尼加拉瓜填充。2019年进入美国的那条线。"},{"name":"The Explorer","color":"#5B3A29","force":"Medium","wrapper":"未公开","vitolas":[],"story":"探险者——与 The Navigator 同为最初两款。"},{"name":"Barbarroja''s Invasion","color":"#8B1A1A","force":"Full","wrapper":"未公开","vitolas":[],"story":"海盗巴巴罗萨。这家的调性。"}]',
        'أدفنتورا تعاونٌ، واسمها يكتب ذلك بالحروف الكبيرة: ADV للشريك، وVentura للمصنع. هندرسون فنتورا كبير مزّاجين مشارك وابن ويليام فنتورا الذي يحمل هذا الأطلس بطاقته؛ ومارسيل كنوبل سويسريّ، ساقي نبيذ ومنتج قهوة وتاجرها، جاء إلى السيجار من باب الذوق. أنشآ العلامة سنة 2016، وكلّ شيء يُلفّ في Tabacalera William Ventura بتامبوريل.

يروي الكتالوج رحلاتٍ وقراصنة: The Explorer وThe Navigator وThe Conqueror — غلاف هابانو 2000 إكوادوري، ورباط سومطرة إكوادوري، وحشوتان دومينيكية ونيكاراغوية — ثم The Royal Return وBarbarroja''s Invasion وBlue Eyed Jack''s Revenge. وفي الولايات المتحدة دخلت الدار معرض 2019 باسم ADV & McKay Cigars Co.

علامةٌ تصوّرها سويسريّ ودومينيكي، ولفّها الثاني: يسمّي هذا الأطلس الاثنين، والبلد بلد الورشة.',
        '[{"name":"The Conqueror","color":"#7A2E1E","force":"Medium-Full","wrapper":"هابانو 2000 إكوادوري","vitolas":[],"story":"رباط سومطرة إكوادوري، وحشوتان دومينيكية ونيكاراغوية. خطّ الدخول إلى الولايات المتحدة سنة 2019."},{"name":"The Explorer","color":"#5B3A29","force":"Medium","wrapper":"غير معلن","vitolas":[],"story":"المستكشف — مع The Navigator، أوّل خطّين."},{"name":"Barbarroja''s Invasion","color":"#8B1A1A","force":"Full","wrapper":"غير معلن","vitolas":[],"story":"بربروس، القرصان. نبرة الدار."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);

-- ── Freud Cigar Co. (dominican) ──

INSERT INTO `brands` (`name`, `country_id`, `founded`, `factory`, `source`, `history`, `gamme`, `history_en`, `gamme_en`, `history_es`, `gamme_es`, `history_de`, `gamme_de`, `history_zh`, `gamme_zh`, `history_ar`, `gamme_ar`)
VALUES ('Freud Cigar Co.',
        'dominican',
        '2022 — New York ; chez Tabacalera William Ventura',
        'Sans usine — Tabacalera William Ventura, Tamboril',
        'cigaraficionado.com « Agape Lifestyle Inc. Launches Freud Cigar Co. » et cigar-coop.com « Freud Cigar Company to Debut with SuperEgo » (avril 2022 : fondée par Luis Torres et David Stadnyk, filiale d''Agape Lifestyle Inc. ; SuperEgo, du nom du surmoi de la théorie de Freud, produit par Tabacalera William Ventura) ; finetobacconyc.com (lancement à New York, mai 2022) ; halfwheel.com « Freud SuperEgo Robusto Extra » ; kohnhed.com (AlterEgo, 2023) ; la fiche Tabacalera William Ventura de cet atlas (la fabrique a brûlé le 26 septembre 2022, cinq mois après le lancement)',
        'Freud est une maison de 2022, et elle a eu cinq mois de tranquillité. Luis Torres et David Stadnyk l''ont lancée à New York au printemps, comme filiale d''Agape Lifestyle Inc., avec un premier cigare nommé SuperEgo — le surmoi, la part de la théorie freudienne qui juge. Il est roulé à la Tabacalera William Ventura, à Tamboril, dont l''atlas porte la fiche. Le 26 septembre de la même année, la fabrique a brûlé.

Cette fiche existe donc pour deux raisons. La première est ordinaire : une marque conçue à New York, roulée en République dominicaine, et l''atlas nomme la fabrique. La seconde tient à la date : Freud est la plus jeune des maisons que l''incendie de 2022 a touchées, et sa deuxième ligne, AlterEgo, est sortie en 2023, pendant la reconstruction, depuis les ateliers satellites et El Maestro.

Les noms suivent la théorie — SuperEgo, AlterEgo — et l''on attend l''Ego. La maison ne dit pas encore si elle viendra.',
        '[{"name":"SuperEgo","color":"#3E2A1E","force":"Medium-Full","wrapper":"Non divulguée","vitolas":[],"story":"Le premier cigare, au printemps 2022 — le surmoi. Cinq mois avant l''incendie."},{"name":"AlterEgo","color":"#6B4226","force":"Medium","wrapper":"Non divulguée","vitolas":[],"story":"Sorti en 2023, pendant la reconstruction de la fabrique."}]',
        'Freud is a house of 2022, and it had five months of quiet. Luis Torres and David Stadnyk launched it in New York in the spring, as a subsidiary of Agape Lifestyle Inc., with a first cigar named SuperEgo — the superego, the part of Freudian theory that judges. It is rolled at Tabacalera William Ventura, in Tamboril, whose entry this atlas carries. On 26 September of that same year, the factory burned.

This entry therefore exists for two reasons. The first is ordinary: a brand conceived in New York, rolled in the Dominican Republic, and this atlas naming the factory. The second is the date: Freud is the youngest of the houses the 2022 fire touched, and its second line, AlterEgo, came out in 2023, during the rebuild, from the satellite workshops and El Maestro.

The names follow the theory — SuperEgo, AlterEgo — and one waits for the Ego. The house does not yet say whether it will come.',
        '[{"name":"SuperEgo","color":"#3E2A1E","force":"Medium-Full","wrapper":"Undisclosed","vitolas":[],"story":"The first cigar, spring 2022 — the superego. Five months before the fire."},{"name":"AlterEgo","color":"#6B4226","force":"Medium","wrapper":"Undisclosed","vitolas":[],"story":"Released in 2023, during the rebuilding of the factory."}]',
        'Freud es una casa de 2022, y tuvo cinco meses de tranquilidad. Luis Torres y David Stadnyk la lanzaron en Nueva York en primavera, como filial de Agape Lifestyle Inc., con un primer puro llamado SuperEgo — el superyó, la parte de la teoría freudiana que juzga. Se lía en la Tabacalera William Ventura, en Tamboril, cuya ficha lleva este atlas. El 26 de septiembre de ese mismo año, la fábrica ardió.

Esta ficha existe pues por dos razones. La primera es ordinaria: una marca concebida en Nueva York, liada en la República Dominicana, y este atlas nombra la fábrica. La segunda es la fecha: Freud es la más joven de las casas que el incendio de 2022 tocó, y su segunda línea, AlterEgo, salió en 2023, durante la reconstrucción, desde los talleres satélite y El Maestro.

Los nombres siguen la teoría — SuperEgo, AlterEgo — y se espera el Ego. La casa aún no dice si vendrá.',
        '[{"name":"SuperEgo","color":"#3E2A1E","force":"Medium-Full","wrapper":"No divulgada","vitolas":[],"story":"El primer puro, primavera de 2022 — el superyó. Cinco meses antes del incendio."},{"name":"AlterEgo","color":"#6B4226","force":"Medium","wrapper":"No divulgada","vitolas":[],"story":"Salido en 2023, durante la reconstrucción de la fábrica."}]',
        'Freud ist ein Haus von 2022, und es hatte fünf Monate Ruhe. Luis Torres und David Stadnyk lancierten es im Frühjahr in New York, als Tochter von Agape Lifestyle Inc., mit einer ersten Zigarre namens SuperEgo — das Über-Ich, der Teil der freudschen Theorie, der urteilt. Sie wird in der Tabacalera William Ventura in Tamboril gerollt, deren Eintrag dieser Atlas führt. Am 26. September desselben Jahres brannte die Fabrik.

Dieser Eintrag besteht also aus zwei Gründen. Der erste ist gewöhnlich: eine in New York ersonnene, in der Dominikanischen Republik gerollte Marke, und dieser Atlas nennt die Fabrik. Der zweite liegt im Datum: Freud ist das jüngste der Häuser, die das Feuer von 2022 traf, und seine zweite Linie, AlterEgo, erschien 2023, während des Wiederaufbaus, aus den Satellitenwerkstätten und El Maestro.

Die Namen folgen der Theorie — SuperEgo, AlterEgo — und man wartet auf das Ego. Ob es kommt, sagt das Haus noch nicht.',
        '[{"name":"SuperEgo","color":"#3E2A1E","force":"Medium-Full","wrapper":"Nicht angegeben","vitolas":[],"story":"Die erste Zigarre, Frühjahr 2022 — das Über-Ich. Fünf Monate vor dem Feuer."},{"name":"AlterEgo","color":"#6B4226","force":"Medium","wrapper":"Nicht angegeben","vitolas":[],"story":"Erschienen 2023, während des Wiederaufbaus der Fabrik."}]',
        'Freud 是2022年的公司，安稳了五个月。路易斯·托雷斯与戴维·斯塔德尼克春天在纽约推出它，作为 Agape Lifestyle Inc. 的子公司，首款雪茄名为 SuperEgo——超我，弗洛伊德理论中负责评判的部分。它在坦博里尔的 Tabacalera William Ventura 卷制，本图集载有该厂词条。同年9月26日，工厂失火。

本词条因此有两个存在理由。第一个平常：纽约构思、多米尼加卷制的牌子，本图集点出工厂。第二个在于日期：Freud 是2022年火灾波及的公司中最年轻的一家，其第二条线 AlterEgo 于2023年重建期间由卫星作坊与 El Maestro 推出。

名字循着理论走——SuperEgo、AlterEgo——人们等着 Ego。公司尚未说它是否会来。',
        '[{"name":"SuperEgo","color":"#3E2A1E","force":"Medium-Full","wrapper":"未公开","vitolas":[],"story":"2022年春的第一支——超我。火灾前五个月。"},{"name":"AlterEgo","color":"#6B4226","force":"Medium","wrapper":"未公开","vitolas":[],"story":"2023年、工厂重建期间推出。"}]',
        'فرويد دارٌ من 2022، وقد نعمت بخمسة أشهر من الهدوء. أطلقها لويس توريس وديفيد ستادنيك في نيويورك في الربيع، شركةً تابعة لـAgape Lifestyle Inc.، بسيجار أوّل اسمه SuperEgo — الأنا العليا، الجزء من نظرية فرويد الذي يحكم. يُلفّ في Tabacalera William Ventura بتامبوريل التي يحمل هذا الأطلس بطاقتها. وفي 26 أيلول/سبتمبر من السنة نفسها احترق المصنع.

فلهذه البطاقة إذن سببان. الأوّل عادي: علامة تُصوّرت في نيويورك ولُفّت في جمهورية الدومينيكان، وهذا الأطلس يسمّي المصنع. والثاني في التاريخ: فرويد أصغرُ الدور التي مسّها حريق 2022، وخطّها الثاني، AlterEgo، صدر سنة 2023، أثناء إعادة البناء، من الورش الفرعية وإل مايسترو.

تتبع الأسماء النظرية — SuperEgo وAlterEgo — ويُنتظر الـEgo. ولا تقول الدار بعدُ إن كان سيأتي.',
        '[{"name":"SuperEgo","color":"#3E2A1E","force":"Medium-Full","wrapper":"غير معلن","vitolas":[],"story":"السيجار الأوّل، ربيع 2022 — الأنا العليا. قبل الحريق بخمسة أشهر."},{"name":"AlterEgo","color":"#6B4226","force":"Medium","wrapper":"غير معلن","vitolas":[],"story":"صدر سنة 2023، أثناء إعادة بناء المصنع."}]')
ON DUPLICATE KEY UPDATE `country_id` = VALUES(`country_id`), `founded` = VALUES(`founded`), `factory` = VALUES(`factory`), `source` = VALUES(`source`), `history` = VALUES(`history`), `gamme` = VALUES(`gamme`), `history_en` = VALUES(`history_en`), `gamme_en` = VALUES(`gamme_en`), `history_es` = VALUES(`history_es`), `gamme_es` = VALUES(`gamme_es`), `history_de` = VALUES(`history_de`), `gamme_de` = VALUES(`gamme_de`), `history_zh` = VALUES(`history_zh`), `gamme_zh` = VALUES(`gamme_zh`), `history_ar` = VALUES(`history_ar`), `gamme_ar` = VALUES(`gamme_ar`);


