SELECT
  (SELECT COUNT(*) FROM `brands` WHERE `name` IN ('1502 Cigars','Crux Cigars','Blanco Cigars','Debonaire House','Patoro','ADVentura','Freud Cigar Co.')) = 7 AS sept_fiches,
  (SELECT `country_id` = 'nicaragua' FROM `brands` WHERE `name` = 'Blanco Cigars') AS blanco_nicaragua,
  (SELECT `brands` LIKE '%1502 Cigars%' AND `brands` LIKE '%Blanco Cigars%' FROM `producer_countries` WHERE `id` = 'nicaragua') AS nicaragua_annonce,
  (SELECT `brands` LIKE '%Patoro%' AND `brands` LIKE '%Freud%' FROM `producer_countries` WHERE `id` = 'dominican') AS dominican_annonce,
  (SELECT SUM(CHAR_LENGTH(`detail`) >= 255) = 0 FROM `moderation_log` WHERE `acteur_nom` = 'migration 211') AS journal_non_tronque;
SELECT COUNT(*) AS marques, SUM(TRIM(COALESCE(`source`,'')) = '') AS sans_source FROM `brands`;
